package findu.backend.report.service; import findu.backend.report.dto.*;import findu.backend.report.entity.Report;import findu.backend.report.repository.ReportRepository;import findu.backend.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;@Service @RequiredArgsConstructor public class ReportService{final ReportRepository repo;final UserRepository users;@Transactional public ReportResponse create(Long uid, ReportCreateRequest r){var u=users.findById(uid).orElseThrow(()->new IllegalArgumentException("사용자를 찾을 수 없습니다."));return ReportResponse.from(repo.save(Report.builder().reporter(u).targetType(r.targetType()).targetId(r.targetId()).reason(r.reason()).description(r.description()).status(Report.Status.PENDING).build()));}@Transactional(readOnly=true)public List<ReportResponse> my(Long uid){return repo.findByReporterIdOrderByCreatedAtDesc(uid).stream().map(ReportResponse::from).toList();}@Transactional(readOnly=true)public List<ReportResponse> all(Long uid){requireAdmin(uid);return repo.findAllByOrderByCreatedAtDesc().stream().map(ReportResponse::from).toList();}@Transactional public ReportResponse status(Long uid, Long id, Report.Status st){requireAdmin(uid);var r=repo.findById(id).orElseThrow(()->new IllegalArgumentException("신고를 찾을 수 없습니다."));r.updateStatus(st);return ReportResponse.from(r);}private void requireAdmin(Long uid){var u=users.findById(uid).orElseThrow(()->new IllegalArgumentException("사용자를 찾을 수 없습니다."));if(u.getRole()!=findu.backend.user.entity.Role.ADMIN)throw new org.springframework.security.access.AccessDeniedException("관리자만 접근할 수 있습니다.");}}
